mapper.select:
SELECT c.id, c.no, c.status, c.need_date, c.create_by, c.create_time, COALESCE(agg.buy_count, 0) AS buy_count, COALESCE(agg.converted_count, 0) AS converted_count, nx.id AS next_calc_id, nx.no AS next_calc_no FROM mrp_calc c LEFT JOIN LATERAL (SELECT COUNT(*) FILTER (WHERE i.suggest_qty > 0) AS buy_count, COUNT(*) FILTER (WHERE i.suggest_qty > 0 AND i.converted_qty >= i.suggest_qty) AS converted_count FROM mrp_calc_item i WHERE i.calc_id = c.id AND i.block = 'PURCHASE') agg ON true LEFT JOIN LATERAL (SELECT n.id, n.no FROM mrp_calc n WHERE n.prev_calc_id = c.id AND n.status IN ('DRAFT', 'CONFIRMED') ORDER BY n.id DESC LIMIT 1) nx ON true WHERE true AND c.create_by = #{scope.userId}
AND c.status IN #{s}
AND c.create_by = #{q.createBy} AND (c.create_time AT TIME ZONE 'Asia/Shanghai')::date >= #{q.createDateFrom} AND (c.create_time AT TIME ZONE 'Asia/Shanghai')::date <= #{q.createDateTo}
AND (c.no ILIKE '%' || #{q.keyword} || '%' OR EXISTS (SELECT 1 FROM mrp_calc_order co JOIN ord_order o ON o.id = co.order_id WHERE co.calc_id = c.id AND o.no ILIKE '%' || #{q.keyword} || '%') OR EXISTS (SELECT 1 FROM mrp_calc_order co JOIN ord_order_item oi ON oi.order_id = co.order_id JOIN sty_style s ON s.id = oi.style_id WHERE co.calc_id = c.id AND s.code ILIKE '%' || #{q.keyword} || '%')
OR upper(c.no) IN #{code} OR EXISTS (SELECT 1 FROM mrp_calc_order co JOIN ord_order o ON o.id = co.order_id WHERE co.calc_id = c.id AND upper(o.no) IN #{code}) OR EXISTS (SELECT 1 FROM mrp_calc_order co JOIN ord_order_item oi ON oi.order_id = co.order_id JOIN sty_style s ON s.id = oi.style_id WHERE co.calc_id = c.id AND upper(s.code) IN #{code}) )
ORDER BY c.id DESC
